"use client";

import dynamic from "next/dynamic";
import { useSettings } from "./SettingsProvider";
import CssStarfield from "./CssStarfield";

// Lazy-load the WebGL starfield only when 3D effects are enabled.
const Starfield3D = dynamic(() => import("./Starfield3D"), {
  ssr: false,
  loading: () => null,
});

export default function SpaceBackground() {
  const { effects3D, reducedMotion } = useSettings();
  const useWebGL = effects3D && !reducedMotion;

  return (
    <div className="fixed inset-0 -z-10 bg-[#05030f]" aria-hidden>
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,#160e33_0%,#05030f_60%,#02010a_100%)]" />
      {useWebGL ? <Starfield3D /> : <CssStarfield />}
    </div>
  );
}
